#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/pm/device.h>
#include <zephyr/pm/device_runtime.h>

static const struct device *const dev_reg_0 = DEVICE_DT_GET(DT_NODELABEL(test_reg_0));
static const struct device *const dev_reg_1 = DEVICE_DT_GET(DT_NODELABEL(test_reg_1));
static const struct device *const dev_chained = DEVICE_DT_GET(DT_NODELABEL(test_reg_chained));
static const struct device *const dev_gpio_0 = DEVICE_DT_GET(DT_NODELABEL(test_gpio_0));
static const struct device *const dev_gpio_1 = DEVICE_DT_GET(DT_NODELABEL(test_gpio_1));
static const struct device *const dev_gpio_chained =
	DEVICE_DT_GET(DT_NODELABEL(test_gpio_chained));

static const struct device *const regs[] = {
	DEVICE_DT_GET(DT_NODELABEL(test_reg_0)),
	DEVICE_DT_GET(DT_NODELABEL(test_reg_1)),
	DEVICE_DT_GET(DT_NODELABEL(test_reg_chained)),
};

ZTEST(device_power_domain, test_device_power_domain)
{
	/* 1. Test that all devices are on after initialization */
	for (size_t i = 0; i < ARRAY_SIZE(regs); i++) {
		zassert_true(pm_device_is_powered(regs[i]), "%s is off", regs[i]->name);
	}

	/* 2. Enable runtime power management on regulators */
	printk("Enabling runtime power management on regulators\n");
	for (size_t i = 0; i < ARRAY_SIZE(regs); i++) {
		zassert_ok(pm_device_runtime_enable(regs[i]), "Failed to enable runtime PM");
	}

	/* After enabling runtime PM, devices with 0 usage count should be suspended */
	zassert_false(pm_device_is_powered(dev_reg_0), "dev_reg_0 should be off");
	zassert_false(pm_device_is_powered(dev_reg_1), "dev_reg_1 should be off");
	zassert_false(pm_device_is_powered(dev_chained), "dev_chained should be off");

	/* GPIOs should also be off as they depend on regulators */
	zassert_false(pm_device_is_powered(dev_gpio_0), "dev_gpio_0 should be off");
	zassert_false(pm_device_is_powered(dev_gpio_1), "dev_gpio_1 should be off");
	zassert_false(pm_device_is_powered(dev_gpio_chained), "dev_gpio_chained should be off");

	/* 3. Test that getting a device powers it and its domain on */
	zassert_ok(pm_device_runtime_get(dev_gpio_chained), "Failed to get chained GPIO");
	zassert_true(pm_device_is_powered(dev_gpio_chained), "dev_gpio_chained should be on");
	zassert_true(pm_device_is_powered(dev_chained), "dev_chained should be on");
	zassert_true(pm_device_is_powered(dev_reg_1), "dev_reg_1 should be on");
	/* test_reg_0 is not part of the chain, so it should be off */
	zassert_false(pm_device_is_powered(dev_reg_0), "dev_reg_0 should be off");

	/* 4. Test that putting a device powers it and its domain off */
	zassert_ok(pm_device_runtime_put(dev_gpio_chained), "Failed to put chained GPIO");
	zassert_false(pm_device_is_powered(dev_gpio_chained), "dev_gpio_chained should be off");
	zassert_false(pm_device_is_powered(dev_chained), "dev_chained should be off");
	zassert_false(pm_device_is_powered(dev_reg_1), "dev_reg_1 should be off");

	/* 5. Test that devices can be controlled directly */
	for (size_t i = 0; i < ARRAY_SIZE(regs); i++) {
		const struct device *dev = regs[i];

		printk("Cycling: %s\n", dev->name);
		(void)pm_device_action_run(dev, PM_DEVICE_ACTION_RESUME);
		zassert_true(pm_device_is_powered(dev), "%s should be ON", dev->name);

		(void)pm_device_action_run(dev, PM_DEVICE_ACTION_SUSPEND);
		zassert_false(pm_device_is_powered(dev), "%s should be OFF", dev->name);
	}
}

ZTEST_SUITE(device_power_domain, NULL, NULL, NULL, NULL, NULL);
